import importlib.util, itertools, random, subprocess, json, os

spec = importlib.util.spec_from_file_location("relay", "relay.py")
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

random.seed(20261001)
KINDS = ["relay", "terminal", "pseudo"]

def brute(names, links, kind, s, d, limit):
    adj = {n: [] for n in names}
    for (u, v), (c, up) in links.items():
        if up:
            adj[u].append((v, c))
    best = None  # (cost, fhops, path)
    # DFS simple paths
    stack = [(s, [s], 0, set([s]))]
    while stack:
        node, path, cost, seen = stack.pop()
        if node == d:
            fhops = sum(1 for x in path[1:] if kind[x] != "pseudo")
            key = (cost, fhops, path)
            if best is None or key < best:
                best = key
            continue
        for to, w in adj[node]:
            if to in seen or to == s:
                continue
            if kind[to] == "terminal" and to != d:
                continue
            stack.append((to, path + [to], cost + w, seen | {to}))
    if best is None:
        return {"source": s, "destination": d, "status": "unreachable",
                "cost": None, "topologyPath": [], "forwardPath": [],
                "hops": 0, "trace": [[0, s]]}
    cost, fhops, path = best
    if cost > m.MAX_TIME:
        return ("OVERFLOW",)
    trace = [[0, s]]; fpath = [s]; clock = 0; hops = 0
    status = "delivered" if s == d else None
    for node in path[1:]:
        if hops == limit:
            status = "hop_limit"; break
        if kind[node] == "pseudo":
            continue
        clock += 1; hops += 1
        trace.append([clock, node]); fpath.append(node)
        if node == d:
            status = "delivered"; break
    if status is None:
        status = "hop_limit"
    return {"source": s, "destination": d, "status": status, "cost": cost,
            "topologyPath": path, "forwardPath": fpath,
            "hops": hops, "trace": trace}

fails = 0
for trial in range(3000):
    V = random.randint(1, 6)
    names = [chr(0x61 + i) if i < 26 else f"n{i}" for i in range(V)]
    kind = {n: random.choice(KINDS) for n in names}
    linkmap = {}
    for u, v in itertools.permutations(names, 2):
        if random.random() < 0.35:
            linkmap[(u, v)] = (random.randint(1, 6), random.random() < 0.8)
    links = [{"from": u, "to": v, "cost": c, "up": up}
             for (u, v), (c, up) in linkmap.items()]
    nonpseudo = [n for n in names if kind[n] != "pseudo"]
    if len(nonpseudo) < 1:
        continue
    s = random.choice(nonpseudo)
    d = random.choice(names)
    if kind[d] == "pseudo":
        continue
    limit = random.randint(0, 5)
    ref = brute(names, linkmap, kind, s, d, limit)
    if isinstance(ref, tuple):
        continue  # overflow cannot arise with these small costs
    got = m.compute_rolepath(names, links, kind, s, d, limit)
    if got != ref:
        fails += 1
        print("MISMATCH", trial, s, d, limit, kind)
        print("links:", linkmap)
        print("ref:", ref)
        print("got:", got)
        if fails > 3:
            break
print("fuzz done, fails =", fails)
